			t.Fatal("expected error")
		}
	})
	t.Run("symlink inside snapshots", func(t *testing.T) {
		root := filepath.Join(t.TempDir(), "vault")
		store := New(root)
		entry, err := store.Put("a.txt", writeFile(t, "data"))
		if err != nil {
